source("smoke_firm_dir/code/fxns/1_paths.R")
library(data.table)
input <- file.path(OUT_DIR,"static_pricing_subgame/observed_recovery_2026-10-27/fringe_market_recovery.csv")
out <- file.path(OUT_DIR,"dynamic_entry_exit/constant_fringe_2026-11-03")
dir.create(out,recursive=TRUE,showWarnings=FALSE)
hash <- tools::md5sum(input)
d <- fread(input)
stopifnot(nrow(d)==132L,!anyDuplicated(d$month),all(is.finite(d$delta_F)))
value <- median(d$delta_F)
result <- data.table(delta_F_constant=value,months=nrow(d),first_month=min(d$month),last_month=max(d$month),method="Unweighted median of monthly calibrated total fringe utility")
fwrite(result,file.path(out,"constant_fringe_utility.csv"))
saveRDS(list(delta_F_constant=value,definition="Median calibrated total fringe utility over 132 months; not a fixed fringe share or separate fixed price/quality components."),file.path(out,"constant_fringe_inputs.rds"))
stopifnot(identical(unname(hash),unname(tools::md5sum(input))))
fwrite(data.table(path=input,md5=unname(hash)),file.path(out,"input_hash.csv"))
writeLines(c("Initial dynamic specification: passive fringe total utility is constant across time and industry states.","Constant is the unweighted median of 132 historical monthly calibrated delta_F values, including unobserved quality.","Fringe share and quantity still respond to incumbent prices, qualities, entry/exit and market size.","No separate fringe price, quality or residual transition is introduced; fringe is not a strategic pricing firm.","Historical variation is deliberately suppressed for this first version. Historical recovery and pricing audit inputs remain unchanged.","Validation passed: 132 distinct months, finite utilities, unchanged source hash."),file.path(out,"README.txt"))
print(result,digits=12)
